import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';

import Login from './components/Login';
import Hacker from './components/Hacker';
import Jury from './components/Jury';

import logoWiempower from './Assets/logo_wiempower.png';
import logoGMC from './Assets/GMC.png';
import logoIEEE from './Assets/TunisiaSection.png';



function App(){
	return (
		<div className="app" style={{
			backgroundImage: 'url(/Assets/bg.jpg)',
			backgroundRepeat: 'repeat',
			minHeight: '100vh',
		}}>
			   <header style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}>
				   <img src={logoWiempower} alt="WiEmpower Logo" style={{height:48}} />
				   <img src={logoGMC} alt="GOMYCODE Logo" style={{height:36}} />
				   <img src={logoIEEE} alt="IEEE Tunisia" style={{height:36}} />
				   <span style={{fontWeight:700,fontSize:22,marginLeft:16}}>WiEmpower Hackathon Portal</span>
			   </header>
			<Routes>
				<Route path="/" element={<Navigate to="/login" replace />} />
				<Route path="/login" element={<Login />} />
				<Route path="/hacker" element={<Hacker />} />
				<Route path="/jury" element={<Jury />} />
			</Routes>
		</div>
	);
}


export default App;
